  "benefits": {
    "title": "Key Advantages of the Philippines Individual Tax Structure",
    "html": "<ul class=\"list-disc pl-6 space-y-3\">\n  <li><strong>Universal ₱250,000 Exemption:</strong> Minimum wage earners and entry-level professionals are completely shielded from personal income taxes under Section 24 of the NIRC.</li>\n  <li><strong>Substituted Filing Convenience:</strong> Employees with single employers during the tax year are eligible for substituted filing (BIR Form 2316), eliminating the necessity of filing BIR Form 1700 individually.</li>\n  <li><strong>8% Flat Tax Option for Freelancers:</strong> Self-employed individuals and online freelancers earning under ₱3,000,000 can simplify bookkeeping by opting for a single 8% flat tax on gross receipts over ₱250,000.</li>\n  <li><strong>Tax-Free 13th Month Pay:</strong> Mandatory 13th-month pay and productivity bonuses up to ₱90,000 are 100% tax-free under statutory rules.</li>\n</ul>"
  },
  "limitations": {
    "title": "Statutory Nuances & Exclusions",
    "html": "<ul class=\"list-disc pl-6 space-y-3\">\n  <li><strong>No Itemized Personal Allowances for Employees:</strong> The TRAIN Law abolished individual personal and additional dependent exemptions; individual compensation earners receive only the standard ₱250,000 threshold.</li>\n  <li><strong>Multiple Employers Requirement:</strong> Employees who switch employers mid-year or hold concurrent jobs are disqualified from substituted filing and must consolidate income on BIR Form 1700 by April 15.</li>\n  <li><strong>Non-Resident Alien Rules:</strong> Non-resident aliens not engaged in trade or business (NRANETB) are taxed at a flat 25% gross withholding rate without benefit of progressive brackets.</li>\n</ul>"
  },
  "commonMistakes": {
    "title": "Frequent Mistakes in Philippines Tax Planning",
    "html": "<ul class=\"list-disc pl-6 space-y-3\">\n  <li><strong>Including 13th Month Pay in Taxable Income:</strong> Adding the full 13th-month salary without deducting the statutory ₱90,000 non-taxable ceiling results in unnecessary over-taxation.</li>\n  <li><strong>Confusing the 8% Self-Employed Option with Compensation:</strong> The 8% optional flat tax applies exclusively to gross receipts of self-employed individuals and freelancers, never to pure compensation income from employment.</li>\n  <li><strong>Failing to Annualize Taxes in December:</strong> Employers must perform a year-end payroll reconciliation (annualization) to refund excess withholdings or withhold remaining shortages on December payslips.</li>\n</ul>"
  },
